<?php
namespace App\Policies; use App\Enums\ContractStatus; use App\Models\{Contract,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class ContractPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_contract');} public function view(User $u,Contract $r):bool{return $this->canForRecord($u,'view_contract',$r);} public function create(User $u):bool{return $u->can('create_contract');} public function update(User $u,Contract $r):bool{return $this->canForRecord($u,'update_contract',$r)&&$r->status===ContractStatus::Draft;} public function delete(User $u,Contract $r):bool{return false;} public function deleteAny(User $u):bool{return false;} public function restore(User $u,Contract $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function forceDelete(User $u,Contract $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function replicate(User $u):bool{return false;} public function reorder(User $u):bool{return false;} }
